BEGIN;

ALTER TABLE ops.record_import_session ADD COLUMN IF NOT EXISTS source_purged_at timestamptz,ADD COLUMN IF NOT EXISTS chunks_purged_at timestamptz,ADD COLUMN IF NOT EXISTS error_report_purged_at timestamptz;
ALTER TABLE ops.record_export_request ADD COLUMN IF NOT EXISTS artifact_purged_at timestamptz;
CREATE TABLE IF NOT EXISTS ops.record_transfer_retention_policy(tenant_id uuid PRIMARY KEY,abandoned_session_days integer NOT NULL DEFAULT 7,source_file_days integer NOT NULL DEFAULT 7,error_report_days integer NOT NULL DEFAULT 30,export_artifact_days integer NOT NULL DEFAULT 30,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,CONSTRAINT record_transfer_retention_policy_days_chk CHECK(abandoned_session_days BETWEEN 1 AND 3650 AND source_file_days BETWEEN 1 AND 3650 AND error_report_days BETWEEN 1 AND 3650 AND export_artifact_days BETWEEN 1 AND 3650));
CREATE INDEX IF NOT EXISTS record_import_session_cleanup_idx ON ops.record_import_session(created_at) WHERE source_purged_at IS NULL OR error_report_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS record_export_request_cleanup_idx ON ops.record_export_request(completed_at) WHERE artifact_key IS NOT NULL;

CREATE OR REPLACE FUNCTION ops.record_transfer_cleanup_candidates(p_now timestamptz DEFAULT clock_timestamp(),p_limit integer DEFAULT 500) RETURNS TABLE(tenant_id uuid,transfer_kind text,transfer_id uuid,artifact_kind text,object_key text) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,ops AS $$ WITH import_policy AS(SELECT s.*,coalesce(p.abandoned_session_days,7) abandoned_days,coalesce(p.source_file_days,7) source_days,coalesce(p.error_report_days,30) report_days FROM ops.record_import_session s LEFT JOIN ops.record_transfer_retention_policy p USING(tenant_id)),export_policy AS(SELECT e.*,coalesce(p.export_artifact_days,30) artifact_days FROM ops.record_export_request e LEFT JOIN ops.record_transfer_retention_policy p USING(tenant_id)),candidates(tenant_id,transfer_kind,transfer_id,artifact_kind,object_key) AS(SELECT tenant_id,'import'::text,id,'source'::text,format('record-transfers/%s/imports/%s/quarantine/source.upload',tenant_id,id) FROM import_policy WHERE source_purged_at IS NULL AND((status IN('committed','cancelled','failed') AND coalesce(completed_at,cancelled_at,created_at)<p_now-make_interval(days=>source_days))OR(status NOT IN('committed','cancelled','failed') AND created_at<p_now-make_interval(days=>abandoned_days))) UNION ALL SELECT tenant_id,'import',id,'error_report',error_report_key FROM import_policy WHERE error_report_key IS NOT NULL AND coalesce(completed_at,cancelled_at,created_at)<p_now-make_interval(days=>report_days) UNION ALL SELECT tenant_id,'export',id,'artifact',artifact_key FROM export_policy WHERE artifact_key IS NOT NULL AND completed_at IS NOT NULL AND completed_at<p_now-make_interval(days=>artifact_days)) SELECT * FROM candidates ORDER BY transfer_kind,transfer_id,artifact_kind LIMIT greatest(1,least(p_limit,5000)); $$;
CREATE OR REPLACE FUNCTION ops.acknowledge_record_transfer_cleanup(p_tenant_id uuid,p_transfer_kind text,p_transfer_id uuid,p_artifact_kind text,p_object_key text,p_purged_at timestamptz DEFAULT clock_timestamp()) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ops AS $$ DECLARE v_changed bigint:=0; BEGIN IF p_transfer_kind='import' AND p_artifact_kind='source' AND p_object_key=format('record-transfers/%s/imports/%s/quarantine/source.upload',p_tenant_id,p_transfer_id) THEN UPDATE ops.record_import_session SET source_purged_at=p_purged_at,chunks_purged_at=p_purged_at,status=CASE WHEN status IN('committed','cancelled','failed') THEN status ELSE 'cancelled' END,cancelled_at=CASE WHEN status IN('committed','cancelled','failed') THEN cancelled_at ELSE p_purged_at END,updated_at=p_purged_at WHERE tenant_id=p_tenant_id AND id=p_transfer_id AND source_purged_at IS NULL;GET DIAGNOSTICS v_changed=ROW_COUNT;IF v_changed=1 THEN DELETE FROM ops.record_import_chunk WHERE tenant_id=p_tenant_id AND session_id=p_transfer_id;END IF; ELSIF p_transfer_kind='import' AND p_artifact_kind='error_report' THEN UPDATE ops.record_import_session SET error_report_key=NULL,error_report_purged_at=p_purged_at,updated_at=p_purged_at WHERE tenant_id=p_tenant_id AND id=p_transfer_id AND error_report_key=p_object_key;GET DIAGNOSTICS v_changed=ROW_COUNT; ELSIF p_transfer_kind='export' AND p_artifact_kind='artifact' THEN UPDATE ops.record_export_request SET artifact_key=NULL,artifact_purged_at=p_purged_at WHERE tenant_id=p_tenant_id AND id=p_transfer_id AND artifact_key=p_object_key;GET DIAGNOSTICS v_changed=ROW_COUNT; ELSE RAISE EXCEPTION 'Invalid transfer cleanup acknowledgement';END IF;RETURN v_changed=1;END $$;
CREATE OR REPLACE FUNCTION ops.record_transfer_stuck_counts(p_now timestamptz DEFAULT clock_timestamp(),p_stuck_after_minutes integer DEFAULT 15) RETURNS TABLE(transfer_kind text,stuck_count bigint) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,ops AS $$ SELECT 'import'::text,count(*) FROM ops.record_import_session WHERE status='running' AND coalesce(updated_at,started_at,created_at)<p_now-make_interval(mins=>greatest(1,p_stuck_after_minutes)) UNION ALL SELECT 'export'::text,count(*) FROM ops.record_export_request WHERE status='running' AND coalesce(started_at,requested_at)<p_now-make_interval(mins=>greatest(1,p_stuck_after_minutes)); $$;

ALTER TABLE ops.record_transfer_retention_policy ENABLE ROW LEVEL SECURITY;ALTER TABLE ops.record_transfer_retention_policy FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS record_transfer_retention_policy_tenant_read ON ops.record_transfer_retention_policy;CREATE POLICY record_transfer_retention_policy_tenant_read ON ops.record_transfer_retention_policy FOR SELECT TO athyperapp USING(tenant_id=shared.current_tenant_id_soft());
DROP POLICY IF EXISTS record_transfer_retention_policy_admin_access ON ops.record_transfer_retention_policy;CREATE POLICY record_transfer_retention_policy_admin_access ON ops.record_transfer_retention_policy FOR ALL TO athyperadmin USING(true) WITH CHECK(true);
REVOKE ALL ON ops.record_transfer_retention_policy FROM PUBLIC;GRANT SELECT ON ops.record_transfer_retention_policy TO athyperapp;GRANT ALL PRIVILEGES ON ops.record_transfer_retention_policy TO athyperadmin;
REVOKE ALL ON FUNCTION ops.record_transfer_cleanup_candidates(timestamptz,integer),ops.acknowledge_record_transfer_cleanup(uuid,text,uuid,text,text,timestamptz),ops.record_transfer_stuck_counts(timestamptz,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.record_transfer_cleanup_candidates(timestamptz,integer),ops.acknowledge_record_transfer_cleanup(uuid,text,uuid,text,text,timestamptz),ops.record_transfer_stuck_counts(timestamptz,integer) TO athyperapp,athyperadmin;
COMMIT;
